head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.hideDebugCtrls();
        $c.libRoundPanel.PanelToGroupBox(panel_1);
        scwin.resizeToWin();
        await scwin.setHeader();
        scwin.init();
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30004.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    // if(gLdMktTp == '1' || gDepCd == 'ZSYS' || js_dep_cd == '1M30')    panel_reg.style.visibility = "";
    panel_reg.style.visibility = "";
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_AddRow_onclick
 * @description 「행삽입」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_AddRow_onclick = function() {
    try {
        dts_Grid.insertRow();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30004.btn_AddRow_onclick" });
    }
};

/**
 * @method
 * @name btn_DelRow_onclick
 * @description 「행삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_DelRow_onclick = function() {
    try {
        dts_Grid.removeRow(dts_Grid.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30004.btn_DelRow_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnPopup
 * @description grd Grid On Popup 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} data 데이터
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnPopup = async function(row, colid, data) {
    try {
        if (colid === "ADM_DEADLINE_DD") {
            // 관리기한 ADM_DEADLINE_DD => 달력 띄워야함.
            dts_Grid.setCellData(dts_Grid.getRowPosition(), "ADM_DEADLINE_DD", vResVal);
        } else {
            // 관리항목 SCHDL_ADM_ITM_TP_CD => 관리항목선택창(30002) 띄워야함.
            const options = {
                id: "ULDSTF30002",
                title: "관리항목유형",
                type: "browserPopup",
                width: "10px",
                height: "20px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/dsclmgt/ULDSTF30002.gfm", options);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30004.grd_Grid_OnPopup" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    // alert_parse(dts_Grid.Text, ",");

};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30004.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
        await $c.win.alert(trs_Save.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30004.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30004.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Read_OnSuccess
 * @description Read On Success 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Read_OnSuccess = function() {
    try {
        dts_Grid.removeAll();
        $c.stf.copyDataSet(dts_Obj, dts_Grid, "");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30004.trs_Read_OnSuccess" });
    }
};

/**
