};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30004.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30004.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30004.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30004.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30004.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30004.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30004.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30004.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30004.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name btn_Search_Isur_Cd_onclick
 * @description btn_Search_Isur_Cd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_Isur_Cd_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30004.btn_Search_Isur_Cd_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30004.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name icn_SCal_onclick
 * @description icn_SCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_SCal_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30004.icn_SCal_onclick" });
    }
};

/**
 * @method
 * @name icn_ECal_onclick
 * @description icn_ECal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_ECal_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30004.icn_ECal_onclick" });
    }
};

/**
 * @method
 * @name btn_reg_onclick
 * @description 「등록」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_reg_onclick = async function() {
    try {
        if (await scwin.checkPeriod()) {
            if ($c.stf.compareFromToDate(edt_SDate, edt_EDate, "시작일", "종료일")) {
                await scwin.setPeriod();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30004.btn_reg_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_STAT_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_STAT_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    url += "&SCREN_ID=" + 'ULDSTF30004.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions2 = {
        id : "sbm_dts_Grid",
        action : "/DisclosureSchedule.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_dts_Master",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Master=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Master.insertRow();
};

/**
 * @method
 * @name setPeriod
 * @description set Period 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setPeriod = async function() {
    dts_Grid.removeAll();
    let sdate = edt_SDate.getValue();
    let edate = edt_EDate.getValue();
    const std = cmb_std.getValue();
    const prd = cmb_prd.getValue();
    const ord = cmb_ord.getValue();

    // alert(sdate + "\n" + edate + "\n" + std + "\n" + prd + "\n" + ord);
    if (ord === '1') // 정순

    {
        const begday = sdate.substr(6, 2); // 입력받은 시작일
        if (std === '1') // 일자기준

        {
            dts_Grid.setBroadcast(false);
            for (let i = 1; sdate < edate; i++) {
                sdate = scwin.getPlusMonth(sdate.substr(0, 4), sdate.substr(4, 2), begday, i === 1 ? 0 : prd);
                let maxday = $c.ut.cGetMaxDay(sdate.substr(0, 4), sdate.substr(4, 2)); // 해당월의 막날
                if (maxday < begday) sdate = $c.ut.cGetMinusMonth(sdate.substr(0, 4), sdate.substr(4, 2), maxday, 0);
                if (sdate < edate) {
                    dts_Grid.insertRow();
                    dts_Grid.setCellData(i, "ADM_DEADLINE_DD", sdate);
                }
            }
            dts_Grid.setBroadcast(true, true);
        } else if (std === '2') // 말일기준

        {
            dts_Grid.setBroadcast(false);
            for (let i = 1; sdate < edate; i++) {
                sdate = scwin.getPlusMonth(sdate.substr(0, 4), sdate.substr(4, 2), edate.substr(6, 2), i === 1 ? 0 : prd);
                if (sdate < edate) {
                    dts_Grid.insertRow();
                    dts_Grid.setCellData(i, "ADM_DEADLINE_DD", scwin.getPlusMonth(sdate.substr(0, 4), sdate.substr(4, 2), $c.ut.cGetMaxDay(sdate.substr(0, 4), sdate.substr(4, 2)), 0));
                }
            }
            dts_Grid.setBroadcast(true, true);
        }
    } else if (ord === '2') // 역순

    {
        const endday = edate.substr(6, 2); // 입력받은 종료일
        if (std === '1') // 일자기준

        {
            dts_Grid.setBroadcast(false);
            for (let i = 1; sdate < edate; i++) {
                edate = $c.ut.cGetMinusMonth(edate.substr(0, 4), edate.substr(4, 2), endday, i === 1 ? 0 : prd);
                let maxday = $c.ut.cGetMaxDay(edate.substr(0, 4), edate.substr(4, 2)); // 해당월의 막날
                if (maxday < endday) edate = $c.ut.cGetMinusMonth(edate.substr(0, 4), edate.substr(4, 2), maxday, 0);
                if (sdate < edate) {
                    dts_Grid.insertRow();
                    dts_Grid.setCellData(i, "ADM_DEADLINE_DD", edate);
                }
            }
            dts_Grid.setBroadcast(true, true);
        } else if (std === '2') // 말일기준

        {
            const yyyy = edate.substr(0, 4);
            const mm = edate.substr(4, 2);
            let maxday = $c.ut.cGetMaxDay(yyyy, mm); // 해당월의 막날

            if (maxday !== endday) // 말일아니면

            {
                edate = scwin.getPlusMonth(yyyy, mm, '01', 0); // 이번달 1일 기준

            } else {
                edate = scwin.getPlusMonth(yyyy, mm, '01', 1); // 다음달 1일 기준

            }
            dts_Grid.setBroadcast(false);
            for (let i = 1; sdate < edate; i++) {
                edate = $c.ut.cGetMinusMonth(edate.substr(0, 4), edate.substr(4, 2), '01', i === 1 ? 0 : prd);
                if (sdate < edate) {
                    dts_Grid.insertRow();
                    dts_Grid.setCellData(i, "ADM_DEADLINE_DD", $c.ut.cGetMinusDate2(edate, 1));
                }
            }
            dts_Grid.setBroadcast(true, true);
        }
    }

    // 휴일체크
    trs_Read.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Read",
        action : "/DisclosureSchedule.do",
        ref : "dts_Grid,dts_Obj",
        target : "trs_Read=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.checkForm()) {
        let res = window.confirm("[저장]하시겠습니까?");
        if (res) {
            dts_Master.setCellData(1, "EMP_NO", js_emp_no);
            trs_Save.KeyName = "toinb_dataid4";
            const sbmOptions = {
                id : "sbm_trs_Save",
                action : "/DisclosureSchedule.do",
                ref : "dts_Master,dts_Grid",
                target : "trs_Save=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name resizeToWin
 * @description resize To Win 처리
 * @returns {void}
 * @hidden N
 */
scwin.resizeToWin = function() {
    frame.Width = 610;
    frame.Height = 580;
};

/**
 * @method
 * @name hideDebugCtrls
 * @description 키값으로 사용하지만 화면상에 표시될 필요가 없는 것들
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    // 키값으로 사용하지만 화면상에 표시될 필요가 없는 것들
    txb_ACPT_NO.hide();
};

/**
 * @method
 * @name checkPeriod
 * @description check Period 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkPeriod = async function() {
    if (edt_SDate.getValue() === "") {
        await $c.win.alert("[관리기간]을 입력하세요.");
        edt_SDate.focus();
        return false;
    }
    if (edt_EDate.getValue() === "") {
        await $c.win.alert("[관리기간]을 입력하세요.");
        edt_EDate.focus();
        return false;
    }
    if (cmb_std.getValue() === "") {
        await $c.win.alert("[관리기준]을 선택하세요.");
        cmb_std.focus();
        return false;
    }
    if (cmb_prd.getValue() === "") {
        await $c.win.alert("[관리주기]를 선택하세요.");
        cmb_prd.focus();
        return false;
    }
    if (cmb_ord.getValue() === "") {
        await $c.win.alert("[정/역순]을 선택하세요.");
        cmb_ord.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name getPlusMonth
 * @description get Plus Month 처리
 * @param {*} yyyy yyyy
 * @param {*} mm mm
 * @param {*} dd dd
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.getPlusMonth = function(yyyy, mm, dd, val) {
    let iYear = new Number(yyyy);
    let iMonth = new Number(mm);
    let iDay = new Number(dd);
    let ival = new Number(val);
    let iAddYear = 0;
    if (ival >= 12) {
        iAddYear = new Number(ival / 12);
        iYear = iYear + iAddYear;
        iMonth = iMonth + (ival % 12);
    } else {
        ival += iMonth;
        if (ival > 12) {
            iYear = iYear + 1;
            iMonth = ival - 12;
        } else {
            iMonth = ival;
        }
    }
    iMaxDay = $c.ut.cGetMaxDay(iYear, iMonth);
    if (iDay > iMaxDay) {
        iDay = iMaxDay;
    }
    return "" + iYear.toString() + $c.ut.cGetZero(iMonth.toString(), 2) + $c.ut.cGetZero(iDay.toString(), 2);
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[회사]를 선택하세요.");
        txb_ISUR_CD.focus();
        return false;
    }
    /*
    if (getObjectValue(txb_COM_NM) == "")
    {
    	alert("[회사]를 선택하세요.");txb_COM_NM.focus();return false;
    }

    if (getObjectValue(txb_ACPT_NO) == "")
    {
    	alert("[공시]를 선택하세요.");txb_ACPT_NO.focus();return false;
    }
     */
    if (txb_RptNm.getValue() === "") {
        await $c.win.alert("[공시]를 선택하세요.");
        txb_RptNm.focus();
        return false;
    }
    if (edt_DISCLS_PUBL_DDTM.getValue() === "") {
        await $c.win.alert("[공시일]를 입력하세요.");
        edt_DISCLS_PUBL_DDTM.focus();
        return false;
    }
    if (cmb_DISCLS_SCHDL_ACT_STAT_CD.getValue() === "") {
        await $c.win.alert("[일정상태]를 선택하세요.");
        cmb_DISCLS_SCHDL_ACT_STAT_CD.focus();
        return false;
    }
    // detail 검사
    const total = dts_Grid.getRowCount();
    for (let i = 0; i < total; i++) {
        const vADM_DEADLINE_DD = dts_Grid.getCellData(i, "ADM_DEADLINE_DD");
        const vSCHDL_ADM_ITM_TP_NM = dts_Grid.getCellData(i, "SCHDL_ADM_ITM_TP_CD");
        if (vADM_DEADLINE_DD === "" && vSCHDL_ADM_ITM_TP_NM !== "") {
            await $c.win.alert(" 관리기한을 입력하지 않았습니다.");
            return false;
        }
        if (vSCHDL_ADM_ITM_TP_NM === "" && vADM_DEADLINE_DD !== "") {
            await $c.win.alert(" 관리항목을 입력하지 않았습니다.");
            return false;
        }
    }
    /*if (total != dTotal)
		{
			alert("저장할 일정이 없거나 관리기한을 입력하지 않았습니다.");return false;
		} */
    // 관리일자가 하나라도 들어왔으면.
    return true;
};

/**
     * @method
     * @name openDiscls
     * @description open Discls 처리
     * @returns {Promise<void>}
     * @hidden N
     */
scwin.openDiscls = async function() {
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[회사]를 선택하세요");
        txb_ISUR_CD.focus();
        return;
    }
    const vISUR_CD = txb_ISUR_CD.getValue();
    const options = {
        id: "ULDSTF30005",
        title: "공시선택",
        type: "browserPopup",
        width: "10px",
        height: "20px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/dsclmgt/ULDSTF30005.gfm", options);
};

/**
 * @method
 * @name grd_Grid_CanColumnPosChange
 * @description grd Grid Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_CanColumnPosChange = async function(row, colid) {
    if (colid === "ADM_DEADLINE_DD") {
        // true => 빠져나옴. false => 갇힘.
        const sDate = dts_Grid.getCellData(row, "ADM_DEADLINE_DD");
        let res = $c.ut.isDate(sDate);
        if (res) {
            return true;
        } else {
            await $c.win.alert("[관리기한]의 날짜형식이 정확하지 않습니다.");
            return false;
        }
    }
    return true;
};
